    32  light_option light_alloc_option(uint16_t option_length)
    33  {
    34          struct _light_option *option = calloc(1, sizeof(struct _light_option));
    35          uint16_t actual_size = 0;
    36
    37          option->option_length = option_length;
    38
    39          PADD32(option_length, &actual_size);
    40          if (actual_size != 0) {
    41                  option->data = calloc(1, actual_size);
    42          }
    43
    44          return option;
    45  }
    46
    47  light_pcapng light_alloc_block(uint32_t block_type, const uint32_t *block_body, uint32_t block_body_length)
    48  {
    49          struct _light_pcapng *pcapng_block = calloc(1, sizeof(struct _light_pcapng));
    50          uint32_t actual_size = 0;
    51          int32_t block_body_size;
    52
    53          pcapng_block->block_type = block_type;
    54
    55          PADD32(block_body_length, &actual_size);
    56
    57          pcapng_block->block_total_length = actual_size; // This value MUST be a multiple of 4.
    58          block_body_size = actual_size - 2 * sizeof(pcapng_block->block_total_length) - sizeof(pcapng_block->block_type);
    59
    60          if (block_body_size > 0) {
    61                  pcapng_block->block_body = calloc(1, block_body_size);
    62                  memcpy(pcapng_block->block_body, block_body, block_body_size);
    63          }
    64
    65          pcapng_block->next_block = NULL;
    66          pcapng_block->options = NULL;
    67
    68          return pcapng_block;
    69  }
    70
    71  void light_free_option(light_option option)
    72  {
    73          free(option->data);
    74          free(option);
    75  }
    76
    77  void light_free_block(light_pcapng pcapng)
    78  {
    79          free(pcapng->block_body);
    80          free(pcapng);
    81  }

