    36  static struct _light_option *__parse_options(uint32_t **memory, const int32_t max_len)
    37  {
    38     if (max_len <= 0) {
    39        return NULL;
    40     }
    41     else {
    42        struct _light_option *opt = calloc(1, sizeof(struct _light_option));
    43        uint16_t actual_length;
    44        uint16_t alignment = sizeof(uint32_t);
    45
    46        uint16_t *local_memory = (uint16_t*)*memory;
    47        uint16_t remaining_size;
    48
    49        opt->custom_option_code = *local_memory++;
    50        opt->option_length = *local_memory++;
    51
    52        actual_length = (opt->option_length % alignment) == 0 ?
    53              opt->option_length :
    54              (opt->option_length / alignment + 1) * alignment;
    55
    56        if (actual_length > 0) {
    57           opt->data = calloc(1, actual_length);
    58           memcpy(opt->data, local_memory, actual_length);
    59           local_memory += (sizeof(**memory) / sizeof(*local_memory)) * (actual_length / alignment);
    60        }
    61
    62        *memory = (uint32_t*)local_memory;
    63        remaining_size = max_len - actual_length - 2 * sizeof(*local_memory);
    64
    65        if (opt->custom_option_code == 0) {
    66           DCHECK_ASSERT(opt->option_length, 0, light_stop);
    67           DCHECK_ASSERT(remaining_size, 0, light_stop);
    68
    69           if (remaining_size) {
    70              // XXX: Treat the remaining data as garbage and discard it form the trace.
    71              *memory += remaining_size / sizeof(uint32_t);
    72           }
    73        }
    74        else {
    75           opt->next_option = __parse_options(memory, remaining_size);
    76        }
    77
    78        return opt;
    79     }
    80  }
